(function(root,factory){const api=factory();if(typeof module==='object')module.exports=api;else root.MartinsFluxos=api;})(globalThis,()=>{'use strict';
function iso(raw){const s=String(raw||'').trim(),m=s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/),v=m?m[3]+'-'+m[2]+'-'+m[1]:s;if(!/^\d{4}-\d{2}-\d{2}$/.test(v)||v.startsWith('0000-'))throw Error('Informe data válida no padrão dd/mm/aaaa');const d=new Date(v+'T12:00:00Z');if(!Number.isFinite(d.getTime())||d.toISOString().slice(0,10)!==v)throw Error('Data inválida');return v;}
function br(raw){if(!raw)return '';const v=iso(raw);return v.slice(8)+'/'+v.slice(5,7)+'/'+v.slice(0,4);}
function dates(raw){const list=String(raw||'').split(/[,;\n]+/).map(x=>x.trim()).filter(Boolean).map(iso);if(!list.length||list.length>31)throw Error('Informe de 1 a 31 datas de destino');return [...new Set(list)];}
const fold=x=>String(x??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function auditOptions(logs,users,modules=[]){const people=new Map();for(const u of users)if(u&&u.nome)people.set('login:'+(u.usuario||u.email||u.id),{key:'login:'+(u.usuario||u.email||u.id),name:u.nome,login:String(u.usuario||u.email||u.id)});for(const l of logs){const login=String(l.usuario||l.login||''),name=String(l.nomeUsuario||l.nome||login||'Usuário não informado'),key=login?'login:'+login:'name:'+name;if(!people.has(key))people.set(key,{key,name,login});}return {users:[...people.values()].sort((a,b)=>a.name.localeCompare(b.name)),modules:[...new Set([...modules,...logs.map(l=>String(l.modulo||'Não informado'))])].sort((a,b)=>a.localeCompare(b))};}
function filterLogs(logs,{user='todos',userName='',module='todos',text='',start='',end=''}={}){const terms=fold(text).split(/\s+/).filter(Boolean);return logs.filter(l=>{const login=String(l.usuario||l.login||''),name=String(l.nomeUsuario||l.nome||login||'Usuário não informado');if(user!=='todos'&&(user.startsWith('login:')?login!==user.slice(6)&&!( !login&&(name===userName||name===user.slice(6))):user.startsWith('name:')?name!==user.slice(5):name!==user))return false;if(module!=='todos'&&String(l.modulo||'Não informado')!==module)return false;let day;try{day=iso(l.data);}catch{day='';}if((start&&(!day||day<start))||(end&&(!day||day>end)))return false;const hay=fold([l.acao,name,login,l.modulo,l.obra,l.funcionario,l.perfil].join(' '));return terms.every(t=>hay.includes(t));});}
// CNPJ: módulo 11 com valores ASCII menos 48, conforme documentação técnica da RFB.
function documentKey(value){if(value===null||value===undefined)return '';if(typeof value!=='string')throw Error('Informe CPF/CNPJ como texto, preservando zeros iniciais');const raw=value.trim().toUpperCase();if(!/^[A-Z0-9.\/\s-]*$/.test(raw))throw Error('CPF/CNPJ contém caracteres inválidos');return raw.replace(/[.\/\s-]/g,'');}
function validDocument(value){let key;try{key=documentKey(value);}catch{return false;}if(/^([0-9])\1+$/.test(key))return false;if(/^\d{11}$/.test(key)){for(const length of [9,10]){let sum=0;for(let i=0;i<length;i++)sum+=Number(key[i])*(length+1-i);if((sum*10)%11%10!==Number(key[length]))return false;}return true;}if(!/^[A-Z0-9]{12}\d{2}$/.test(key))return false;for(const [length,weights]of [[12,[5,4,3,2,9,8,7,6,5,4,3,2]],[13,[6,5,4,3,2,9,8,7,6,5,4,3,2]]]){let sum=0;for(let i=0;i<length;i++)sum+=(key.charCodeAt(i)-48)*weights[i];const remainder=sum%11;if(Number(key[length])!==(remainder<2?0:11-remainder))return false;}return true;}
function saveClient(rows,input,id,newId){if(!Array.isArray(rows))throw Error('Cadastro de clientes inválido; dados preservados');const ids=new Set;for(const c of rows){if(!c||typeof c.id!=='string'||!c.id||ids.has(c.id)||typeof c.nome!=='string')throw Error('Cadastro de clientes com identificação inválida ou duplicada');ids.add(c.id);}const nome=String(input.nome||'').trim();if(!nome||nome.length>200)throw Error('Informe nome do cliente (até 200 caracteres)');const next=structuredClone(rows),existing=id?rows.find(x=>x.id===id):null;if(id&&!existing)throw Error('Cliente alterado ou removido; atualize o cadastro');if(!id&&(typeof newId!=='string'||!newId||ids.has(newId)))throw Error('Identificação de cliente já utilizada ou inválida');if(next.some(x=>x.id!==id&&fold(x.nome.trim())===fold(nome)))throw Error('Nome já cadastrado; selecione e edite o cliente existente');
const doc=Object.hasOwn(input,'doc')?String(input.doc??'').trim():existing?.doc||'';
// Documentos históricos inválidos não são apagados nem corrigidos silenciosamente.
const unchangedLegacy=existing&&doc===String(existing.doc||'');let key='';if(doc&&!unchangedLegacy){if(!validDocument(doc))throw Error('CPF/CNPJ inválido; confira formato e dígitos verificadores');key=documentKey(doc);}else if(validDocument(doc))key=documentKey(doc);
if(key&&next.some(x=>{if(x.id===id)return false;try{return documentKey(x.doc)===key;}catch{return false;}}))throw Error('CPF/CNPJ já cadastrado em outro cliente; selecione o cadastro existente');
const values={nome,doc,tel:String(input.tel??existing?.tel??'').trim(),cidade:String(input.cidade??existing?.cidade??'').trim(),obs:String(input.obs??existing?.obs??'').trim()};if(values.tel.length>100||values.cidade.length>200||values.obs.length>2000||doc.length>100)throw Error('Campos do cliente excedem o limite permitido');let client;if(id){const i=next.findIndex(x=>x.id===id);client=next[i]={...next[i],...values};}else{client={id:newId,...values};next.unshift(client);}return {rows:next,client};}
return {iso,br,dates,fold,auditOptions,filterLogs,documentKey,validDocument,saveClient};});
